// Arguments:
//   - serviceName: Service name
//
// Requires the IAM action vps:apiovh:terminate.
func (s *Service) TerminateVPS(ctx context.Context, serviceName string) (string, error) {
	return ovh.Call[string](ctx, s.c, &ovh.Request{Operation: opTerminateVPS, Method: http.MethodPost, Path: ovh.Path("/v1/vps/{serviceName}/terminate", "serviceName", serviceName)})
}

